import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/**
 * Opens the SQLite database shared by the server and worker processes and makes sure the schema
 * exists. Both processes call this at startup; the schema statements are idempotent.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = NORMAL;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0,
      output TEXT,
      error TEXT,
      idempotency_key TEXT UNIQUE,
      payload TEXT,
      available_at INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS heartbeats (
      name TEXT PRIMARY KEY,
      at INTEGER NOT NULL
    );
  `);
  return db;
}
import { randomUUID } from 'node:crypto';
import type { DatabaseSync, SQLOutputValue } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Attempts allowed in total, including the first. */
export const MAX_ATTEMPTS = 3;
/** A worker heartbeat older than this means the worker is down. */
export const WORKER_STALE_MS = 3000;

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  output: string | null;
  error: string | null;
  payload: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The job as returned by the HTTP API. */
export interface JobJson {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, progress_completed, output, error, payload, available_at, created_at, updated_at';

export function toJson(r: JobRow): JobJson {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.output !== null ? { output: r.output } : null,
    error: r.status === 'failed' ? (r.error ?? 'transient failure') : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** Runs `fn` inside an immediate write transaction, so concurrent writers from other processes wait. */
export function inTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

function one(rows: Record<string, SQLOutputValue> | undefined): JobRow | undefined {
  return rows as unknown as JobRow | undefined;
}

export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE id = ?`).get(id));
}

function getJobBySeq(db: DatabaseSync, seq: number): JobRow | undefined {
  return one(db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE seq = ?`).get(seq));
}

export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare(`SELECT ${COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
}

export function findByIdempotencyKey(db: DatabaseSync, key: string): JobRow | undefined {
  return one(db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(key));
}

export function insertJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | null, payload: string): JobRow {
  const id = randomUUID();
  const ts = new Date().toISOString();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, payload, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
  ).run(id, job.input, job.steps, job.failAttempts, idempotencyKey, payload, ts, ts);
  return getJob(db, id)!;
}

/** Puts jobs left `running` by a previous worker back in the queue. Only one worker runs at a time. */
export function requeueInterrupted(db: DatabaseSync): number {
  const result = db
    .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`)
    .run(new Date().toISOString());
  return Number(result.changes);
}

/** Atomically takes the oldest queued job that is due, and starts an attempt on it. */
export function claimNext(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return inTransaction(db, () => {
    const next = db
      .prepare(`SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`)
      .get(nowMs) as unknown as { seq: number } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?`,
    ).run(new Date().toISOString(), next.seq);
    return getJobBySeq(db, next.seq);
  });
}

export function setProgress(db: DatabaseSync, seq: number, completed: number): void {
  db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?`).run(
    completed,
    new Date().toISOString(),
    seq,
  );
}

export function completeJob(db: DatabaseSync, seq: number, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE seq = ?`,
  ).run(output, new Date().toISOString(), seq);
}

/** Records a failed attempt: requeue with a delay while attempts remain, otherwise mark the job failed. */
export function failAttempt(db: DatabaseSync, job: JobRow, nowMs: number, retryDelayMs: number): void {
  const ts = new Date().toISOString();
  if (job.attempts >= MAX_ATTEMPTS) {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = 'transient failure', progress_completed = 0, updated_at = ? WHERE seq = ?`,
    ).run(ts, job.seq);
  } else {
    db.prepare(
      `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE seq = ?`,
    ).run(nowMs + retryDelayMs, ts, job.seq);
  }
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    `INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`,
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
}

export function workerIsUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare(`SELECT at FROM heartbeats WHERE name = 'worker'`).get() as unknown as { at: number } | undefined;
  return row !== undefined && nowMs - row.at <= WORKER_STALE_MS;
}
import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNext,
  clearHeartbeat,
  completeJob,
  failAttempt,
  requeueInterrupted,
  setProgress,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

const STEP_MS = 100;
const IDLE_MS = 200;
const HEARTBEAT_MS = 1000;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Processes one attempt. A stop request leaves the job `running`; it is requeued on the next start. */
async function runAttempt(job: JobRow): Promise<void> {
  // Attempt n fails at its first step, before any progress, when n <= failAttempts.
  if (job.attempts <= job.fail_attempts) {
    failAttempt(db, job, Date.now(), RETRY_DELAY_MS);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(db, job.seq, step);
  }
  completeJob(db, job.seq, job.input.toUpperCase());
}

// A worker that starts while no other worker is running owns every job still marked running.
const requeued = requeueInterrupted(db);
if (requeued > 0) console.log(`requeued ${requeued} interrupted job(s)`);

writeHeartbeat(db, Date.now());
const heartbeat = (async () => {
  for await (const _ of every(HEARTBEAT_MS)) {
    if (stopping) break;
    try {
      writeHeartbeat(db, Date.now());
    } catch (err) {
      console.error('heartbeat failed:', err);
    }
  }
})();

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNext(db, Date.now());
    if (job) await runAttempt(job);
    else await sleep(IDLE_MS);
  } catch (err) {
    console.error('worker iteration failed:', err);
    await sleep(IDLE_MS);
  }
}

await heartbeat;
clearHeartbeat(db);
db.close();
console.log('worker stopped');
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  findByIdempotencyKey,
  getJob,
  inTransaction,
  insertJob,
  listJobs,
  toJson,
  workerIsUp,
  type NewJob,
} from './jobs.ts';

const MAX_BODY_BYTES = 16 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'] as const;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function notAllowed(res: ServerResponse, allowed: string[]): void {
  send(
    res,
    405,
    { error: { code: 'method_not_allowed', message: `Method not allowed. Use ${allowed.join(' or ')}.` } },
    { allow: allowed.join(', ') },
  );
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Validates a parsed body and applies defaults. Returns every offending field, not just the first. */
export function validateCreate(raw: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (!isPlainObject(raw)) return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(raw)) {
    if (!(ALLOWED_FIELDS as readonly string[]).includes(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  if (!Object.hasOwn(raw, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof raw.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (raw.input.length < 1 || raw.input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (raw.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = raw.input;
  }

  const integer = (name: 'steps' | 'failAttempts', min: number, max: number, dflt: number): number => {
    if (!Object.hasOwn(raw, name)) return dflt;
    const v = raw[name];
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
      return dflt;
    }
    return v;
  };
  const steps = integer('steps', 1, 20, 5);
  const failAttempts = integer('failAttempts', 0, 5, 0);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];

  const contentType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const isJson = contentType === 'application/json';
  if (!isJson) fields.push({ field: 'body', message: 'Content-Type must be application/json' });

  let key: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    const k = String(keyHeader);
    if (IDEMPOTENCY_KEY.test(k)) key = k;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsedValue: NewJob | undefined;
  if (tooLarge) {
    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (isJson) {
    let parsed: unknown;
    let parsedOk = false;
    try {
      parsed = JSON.parse(text);
      parsedOk = true;
    } catch {
      fields.push({ field: 'body', message: 'must be valid JSON' });
    }
    if (parsedOk) {
      const result = validateCreate(parsed);
      if (result.ok) parsedValue = result.value;
      else fields.push(...result.fields);
    }
  }

  const value = parsedValue;
  if (fields.length > 0 || value === undefined) {
    const message = `Invalid request: ${fields.map((f) => `${f.field} ${f.message}`).join('; ')}.`;
    return sendError(res, 400, 'invalid_request', message, fields);
  }

  const payload = JSON.stringify([value.input, value.steps, value.failAttempts]);
  const outcome = inTransaction(db, () => {
    if (key !== null) {
      const existing = findByIdempotencyKey(db, key);
      if (existing) {
        return existing.payload === payload ? { status: 200 as const, job: existing } : { status: 409 as const, job: undefined };
      }
    }
    return { status: 201 as const, job: insertJob(db, value, key, payload) };
  });

  if (outcome.job === undefined) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.status, toJson(outcome.job));
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});
server.listen(Number(process.env.PORT ?? 3000), () => {
  console.log(`server listening on ${process.env.PORT ?? 3000}`);
});

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    return send(res, 200, { status: 'ok', worker: workerIsUp(db, Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobs(db).map(toJson) });
    if (method === 'POST') return createJob(req, res);
    return notAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    const row = getJob(db, match[1]!);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJson(row));
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeAllConnections();
    setTimeout(() => process.exit(0), 2000).unref();
  });
}
