    ul { list-style: none; padding: 0; margin: 0; }
    li { border-bottom: 1px solid #eee; padding: 0.5rem 0; display: grid; grid-template-columns: 1fr auto auto; gap: 0.75rem; align-items: baseline; }
    .meta { font-size: 0.8rem; color: #666; grid-column: 1 / -1; word-break: break-all; }
    [data-testid="job-status"] { font-weight: 600; }
