<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <div class="row">
      <label>Steps (1–20, default 5)
        <input data-testid="job-steps" name="steps" type="number" placeholder="5">
      </label>
      <label>Fail attempts (0–5, default 0)
        <input data-testid="job-fail-attempts" name="failAttempts" type="number" placeholder="0">
      </label>
    </div>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>

  <div data-testid="form-error" role="alert"></div>

  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>

  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const inputEl = document.querySelector('[data-testid="job-input"]');
    const stepsEl = document.querySelector('[data-testid="job-steps"]');
    const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
    const submitBtn = document.querySelector('[data-testid="job-submit"]');
    const errorEl = document.querySelector('[data-testid="form-error"]');
    const listEl = document.querySelector('[data-testid="job-list"]');

    // Numeric text is sent as a number; anything else is sent as typed so the API's validation reports it.
    function toApiValue(raw) {
      const t = raw.trim();
      return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : raw;
    }

    function describeError(data, status) {
      const err = data && data.error;
      if (!err) return `Request failed (HTTP ${status}).`;
      const fields = Array.isArray(err.fields) ? err.fields : [];
      const detail = fields.map((f) => `${f.field} ${f.message}`).join('; ');
      return detail ? `${err.message} ${detail}.` : err.message || `Request failed (HTTP ${status}).`;
    }

    function renderJob(job) {
      const li = document.createElement('li');
      li.setAttribute('data-testid', 'job-item');
      li.dataset.jobId = job.id;

      const input = document.createElement('span');
      input.textContent = job.input;

      const status = document.createElement('span');
      status.setAttribute('data-testid', 'job-status');
      status.textContent = job.status;

      const progress = document.createElement('span');
      progress.setAttribute('data-testid', 'job-progress');
      progress.textContent = `${job.progress.completed}/${job.progress.total}`;

      const result = document.createElement('span');
      result.setAttribute('data-testid', 'job-result');
      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
      else if (job.status === 'failed') result.textContent = job.error || '';
      else result.textContent = '';

      const meta = document.createElement('span');
      meta.className = 'meta';
      meta.textContent = `${job.id} · attempts ${job.attempts}`;

      li.append(input, status, progress, result, meta);
      return li;
    }

    async function refresh() {
      try {
        const res = await fetch('/api/jobs');
        if (!res.ok) return;
        const data = await res.json();
        listEl.replaceChildren(...data.jobs.map(renderJob));
      } catch {
        // Server unreachable; keep the last list and try again on the next tick.
      }
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorEl.textContent = '';
      const body = { input: inputEl.value };
      if (stepsEl.value.trim() !== '') body.steps = toApiValue(stepsEl.value);
      if (failEl.value.trim() !== '') body.failAttempts = toApiValue(failEl.value);

      submitBtn.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        const data = await res.json().catch(() => null);
        if (!res.ok) {
          errorEl.textContent = describeError(data, res.status);
          return;
        }
        inputEl.value = '';
        stepsEl.value = '';
        failEl.value = '';
        await refresh();
      } catch (err) {
        errorEl.textContent = `Could not reach the server: ${err.message}`;
      } finally {
        submitBtn.disabled = false;
      }
    });

    refresh();
    setInterval(refresh, 1000);
  </script>
</body>
