import {openDatabase} from './src/db.ts';
import {insertJob,claimNext,failAttempt,requeueInterrupted,toJson} from './src/jobs.ts';
const db=openDatabase(':memory:');
insertJob(db,{input:'hi',steps:20,failAttempts:2},null,'');
let job=claimNext(db,Date.now());
failAttempt(db,job,Date.now(),0);
job=claimNext(db,Date.now());
failAttempt(db,job,Date.now(),0);
job=claimNext(db,Date.now());
console.log('Before restart:',JSON.stringify(toJson(job)));
requeueInterrupted(db);
console.log('After restart:',JSON.stringify(toJson(claimNext(db,Date.now()))));
db.close();
JS"

